// build/cli-bundle.js — 给命令行宿主裁一份翻译引擎（learning-design §9.10）。
//
// 产物：`dist-cli/engine.js`（或 `dist-cli-china/engine.js`），一个文件，Node 直接
// `require()`。为什么是**同一份字节**而不是重写一遍，见 app/ext-shim.js 的文件头与
// domain-design §2.7：传输那一层每一处调参（四种 wire format、可选字段三态、停机码、
// 重试）都要两份同时改，而漂开的症状是「扩展好好的、CLI 少一个字段」，没有一行日志会说。
//
// 与 build/ext-bundle.js 同形：按顺序拼 IIFE、生成物跟着 flavor 走。差别只在垫片与入口
// —— 那边是 JavaScriptCore（原生给钩子），这边是 Node（自带 fetch/AbortController/定时器）。
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

// 顺序即依赖。垫片必须第一 —— 后面几个在**加载期**就读 `chrome`。
// 这份清单是逐文件 grep 出来的最小集，不是「把 content/ 都拿来」：
//   node-shim       window / chrome.storage.local / chrome.runtime（fetch 等用 Node 自带的）
//   providers.gen   引擎注册表（id / 端点 / 默认模型 / 能力），**生成物，跟 flavor 走**
//   langs.gen       语言注册表，同上
//   engine-state    needsSetup / resolve —— 与设置页、Mac 面板、扩展同一个判据
//   notes           resolveConfig（引擎三元组的唯一解析处）
//   target-lang     「译成」的解析（跟随界面语言时的回落）
//   wire-format     地址 → 传输格式（刻意无依赖）
//   request-shape   发哪些可选字段（查表，不试探）
//   translation-api 四种传输 + 停机码 + 重试
//   cli-entry       MTCli.translate / detectLanguage / providers，最后一个
//
// 刻意**不带**：i18n-messages（1 MB 的全部语种文案；CLI 的少量文案走 cli/messages.js）
// 与 translation-core（33 KB 的字幕引擎；Phase 1 用不上，字幕命令落地时再评估）。
const MODULES = [
  'cli/node-shim.js',
  'extension/content/providers.gen.js',
  'extension/content/langs.gen.js',
  'extension/content/engine-state.js',
  'extension/learn/notes.js',
  'app/target-lang.js',
  'extension/content/wire-format.js',
  'extension/content/request-shape.js',
  'extension/content/translation-api.js',
  'cli/entry.js',
];

// 与 app-bundle / ext-bundle 同一条纪律：**只重定向生成物**。中国版那一份注册表只覆盖到
// `dist-china/content/`，这里照旧读 `extension/` 的话，CLI 拿到的就是国际版注册表。缺了就
// 报错，**不回落**：回落正是「拿到了另一个 flavor 的东西，而全程没有一行警告」那个 bug 的形状。
const GENERATED = new Set(['providers.gen.js', 'langs.gen.js']);

function buildCliBundle(outDir, log, opts) {
  opts = opts || {};
  fs.mkdirSync(outDir, { recursive: true });

  const srcFor = (rel) => {
    if (!opts.genRoot) return path.join(ROOT, rel);
    const base = path.basename(rel);
    if (!rel.startsWith('extension/content/') || !GENERATED.has(base)) return path.join(ROOT, rel);
    const alt = path.join(opts.genRoot, 'content', base);
    if (!fs.existsSync(alt)) throw new Error(`cli bundle: genRoot 里缺 content/${base}（${alt}）`);
    return alt;
  };

  const parts = [
    '// GENERATED by build/cli-bundle.js — do not edit.',
    '// Sources: ' + MODULES.join(', '),
    '',
  ];
  for (const rel of MODULES) {
    const abs = srcFor(rel);
    if (!fs.existsSync(abs)) {
      // 硬失败。少一个模块出来的包会加载成功、第一次用时才抛 —— 那是最难回溯到构建的失败形状。
      throw new Error(`cli bundle: missing source ${rel}`);
    }
    parts.push(`// ─── ${rel} ${'─'.repeat(Math.max(0, 60 - rel.length))}`);
    parts.push(fs.readFileSync(abs, 'utf8'));
    parts.push('');
  }

  const out = parts.join('\n');
  fs.writeFileSync(path.join(outDir, 'engine.js'), out);
  if (log) log(`  ✓ engine.js（${MODULES.length} 个模块，${Math.round(out.length / 1024)} KB）`);
  return out.length;
}

module.exports = { buildCliBundle, MODULES, GENERATED };
